import {LanguageService} from '../../services/language.service';
import {LegalService} from '../../services/legal.service';
import {RegistrationProfileService} from '../../services/registration-profile.service';
import { FormControl } from '@angular/forms';
import { Component } from '@angular/core';
import { FormBuilder, Validators, FormArray, FormGroup } from '@angular/forms';
import {ActivatedRoute,Router } from '@angular/router';

import { UsersService } from 'godigital-lib';               // adjust path if needed
import { StoreDbService, OBJECTNAME } from 'godigital-lib'; // adjust path if needed
import { UtilsService } from 'godigital-lib';

export function registrationRole(value:any):string {return ['assetOwner','boatOwner','owner'].includes(String(value))?'assetOwner':value==='concierge'?'concierge':value==='serviceProvider'?'serviceProvider':'customer';}

type SocialLink = { label: string; url: string };

@Component({
  standalone: false,
  selector: 'app-signup',
  templateUrl: './signup.component.html',
  styleUrls: ['./signup.component.css'],
})
export class SignupComponent {
  legalCatalog:any;legalLabels:any={};legalError='';private legalLoad=0;private legalLanguageSub:any;
  async loadLegal(){const request=++this.legalLoad;this.legalCatalog=null;this.form?.patchValue({acceptTerms:false});try{const catalog=await this.legal.catalog(registrationRole(this.form?.value.role));if(request!==this.legalLoad)return;this.legalCatalog=catalog;this.legalLabels=catalog.labels;this.legalError=this.legalCatalog.accepting?'':this.legalLabels.signupUnavailable;}catch{this.legalError=this.legalLabels.error||'';}}
  publishIntent=false;
  roles:Array<{id:string,labelKey:string}>=[];
  async ngOnInit():Promise<void>{this.publishIntent=this.route?.snapshot.queryParamMap.get('returnUrl')==='/owner/listings';try{this.roles=await this.registrationProfile.roles();if(this.route.snapshot.queryParamMap.get('returnUrl')==='/concierge'&&this.roles.some(r=>r.id==='concierge'))this.form.patchValue({role:'concierge'});else if(this.publishIntent&&this.roles.some(r=>r.id==='assetOwner'))this.form.patchValue({role:'assetOwner'});}catch{this.error='Le catalogue des rôles est indisponible. Réessayez.';}this.legalLanguageSub=this.legalLanguage.language$.subscribe(()=>{void this.loadLegal();});this.form.get('role')?.valueChanges.subscribe(()=>{void this.loadLegal();});}

  ngOnDestroy(){this.legalLanguageSub?.unsubscribe();this.legalLoad++;}
  socialControl(index: number, key: 'label' | 'url'): FormControl {
    return this.socials.at(index).get(key) as FormControl;
  }
  onPhotosInput(event: Event): void {
    void this.onPhotosSelected((event.target as HTMLInputElement | null)?.files || null);
  }

  emailActionWarning='';
  sending = false;
  success = false;                // shown only for email/password flow
  error?: string;                 // non-modal errors (rare)
  // --- modal state ---
  showErrorModal = false;
  errorModalTitle = 'Authentication failed';
  errorModalMessage = 'Something went wrong. Please try again.';

  showSuccessModal = false;
  successModalTitle = 'Account created successfully';
  successModalMessage = 'Your account has been created. Please check your inbox and your Junk/Spam folder if a password setup or validation email was sent, then sign in.';

  form: FormGroup;
  photoUrls: string[] = [];

  /** If true & role is owner/provider, redirect to Stripe Connect after signup */
  connectStripeNow = false;

  constructor(
    private fb: FormBuilder,
    private users: UsersService,
    private storeDb: StoreDbService,
    public utilSvc: UtilsService,
    private router: Router,
    private registrationProfile:RegistrationProfileService,
    private legal:LegalService,
    private legalLanguage:LanguageService,
    private route:ActivatedRoute
  ) {
    this.form = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]],

      firstname: ['', [Validators.required]],
      lastname: ['', [Validators.required]],
      displayName: [''],
      phone: [''],
      country: [''],

      role: ['customer', [Validators.required]],

      socialnetwork: this.fb.array<ReturnType<typeof this.newSocial>>([]),

      acceptTerms: [false, Validators.requiredTrue],
      legalName: ['', [Validators.required,Validators.minLength(2),Validators.maxLength(240)]],
      adultConfirmed: [false, Validators.requiredTrue],
    });
  }

  // ---------- helpers
  get f() { return this.form.controls; }
  get socials() { return this.form.get('socialnetwork') as FormArray; }
  newSocial() { return this.fb.group({ label: [''], url: [''] }); }

  addSocial() { this.socials.push(this.newSocial()); }
  removeSocial(i: number) { this.socials.removeAt(i); }

  private firebaseUser():any {const db:any=this.storeDb;return db.firebaseauth?.currentUser||db.firebaseAuth?.currentUser||db.auth?.currentUser||null;}
  private isOwnerOrProvider(role: string | null | undefined) {
    return ['assetOwner','boatOwner','owner','serviceProvider'].includes(String(role));
  }

  private buildStripeAuthorizeUrl(ownerId: string, role: string) {
    return new URL('/owner/payments',window.location.origin).toString();
  }

  // ---------- modal controls
  openErrorModal(message: string, title = 'Authentication failed') {
    this.errorModalTitle = title;
    this.errorModalMessage = message || 'Something went wrong. Please try again.';
    this.showErrorModal = true;
  }
  closeErrorModal() {
    this.showErrorModal = false;
  }

  openSuccessModal(message?: string, title = 'Account created successfully') {
    this.successModalTitle = title;
    this.successModalMessage = message || 'Your account has been created successfully. Please sign in to continue.';
    this.showSuccessModal = true;
  }

  closeSuccessModal() {
    this.showSuccessModal = false;
    this.router.navigate(['/account/login'], { queryParams: { created: 'true' } });
  }

  // ---------- uploads
  async onPhotosSelected(files: FileList | null) {
    if (!files?.length) return;
    const storeId = this.utilSvc.backendFBstoreId;
    const dir = `users/${Date.now()}`;

    this.sending = true;
    try {
      for (const file of Array.from(files)) {
        const url = await this.storeDb.uploadObjects1(storeId, file, dir) as string;
        this.photoUrls.push(url);
      }
    } catch (e: any) {
      this.openErrorModal(e?.message || 'Photo upload failed', 'Upload failed');
    } finally {
      this.sending = false;
    }
  }

  // ---------- email/password signup
  async signupWithEmail() {
    this.error = undefined;
    this.success = false;
    if (this.form.invalid||!this.legalCatalog?.accepting) {this.form.markAllAsTouched();return;}

    this.sending = true;
    try {
      const v = this.form.value;

      const displayName =
        (v.displayName || '').trim() ||
        `${(v.firstname || '').toString().trim()} ${(v.lastname || '').toString().trim()}`.trim();

      // 1) create auth user
      this.emailActionWarning='';
      const previousUid=this.firebaseUser()?.uid;
      let uid:string;
      try {uid=(await this.users.registerWithEmail(v.email!, v.password!, displayName)).uid;}
      catch(e:any){
        const current=this.firebaseUser();
        if(e?.code==='auth/unauthorized-continue-uri'&&current?.uid&&current.uid!==previousUid&&String(current.email||'').toLowerCase()===String(v.email).trim().toLowerCase()){
          uid=current.uid;this.emailActionWarning='Le compte a été créé, mais Firebase a refusé l’envoi du courriel de validation. Ajoutez le domaine de l’URL de retour dans Authentication > Settings > Authorized domains, puis renvoyez le courriel. Le compte n’est pas marqué comme vérifié.';
        }else throw e;
      }

      // 2) profile
      const now = Date.now();
      const profile = {
        userId: uid,
        firstname: v.firstname,
        lastname: v.lastname,
        country: v.country || '',
        stripeAccountId: '',
        stripeAccountStatus: '',
        email: v.email,
        phone: v.phone || '',
        role: registrationRole(v.role),
        photos: this.photoUrls,
        socialnetwork: (v.socialnetwork || []).map((s: any) => ({
          label: s.label || '',
          url: s.url || '',
        })) as SocialLink[],
        emailverified: false,
        state: 'active',
        displayName: displayName,
        createdTS: now,
        modifiedTS: now,
        photoURL: this.photoUrls[0] || '',
        provider: 'firebase',
      };

      await this.legal.accept(this.legalCatalog,v.legalName,v.adultConfirmed);

      // 3) save to RTDB
      await this.registrationProfile.save(profile);

      // 4) Either redirect to Stripe immediately, or show the success banner (as before)
      if (this.connectStripeNow && this.isOwnerOrProvider(profile.role) && !this.emailActionWarning) {
        window.location.href = this.buildStripeAuthorizeUrl(uid, profile.role);
        return;
      }

      // Send a password setup/reset email when available so the user can validate or reset access cleanly.
      try {
        await this.users.resetPwdUser(v.email);
      } catch {
        // Best effort only: some Firebase configurations may not allow reset immediately after creation.
      }

      this.success = true;
      this.form.reset({ role: 'customer', acceptTerms: false,adultConfirmed:false });
      this.photoUrls = [];
      this.openSuccessModal(
        this.emailActionWarning || 'Account created successfully. Please check your inbox and your Junk/Spam folder for the password setup/reset email before signing in.',
        'Account created successfully'
      );

      setTimeout(() => {
        if (this.showSuccessModal && !this.emailActionWarning) {
          this.closeSuccessModal();
        }
      }, 2500);
    } catch (e: any) {
      this.openErrorModal(e?.code==='auth/unauthorized-continue-uri'?'Firebase refuse le domaine de l’URL de retour. Dans Firebase Console > Authentication > Settings > Authorized domains, ajoutez le domaine utilisé (par exemple localhost pour vos tests). Le compte peut déjà avoir été créé : essayez de vous connecter avant de recommencer.':e?.code==='auth/email-already-in-use'?'Cette adresse possède déjà un compte. Connectez-vous ou utilisez Mot de passe oublié.':e?.message || 'Sign-up failed.');
    } finally {
      this.sending = false;
    }
  }

  // ---------- Google signup (IMMEDIATE REDIRECT TO HOME)
  async signupWithGoogle() {
    if(!this.legalCatalog?.accepting||!this.form.value.acceptTerms||!this.form.value.adultConfirmed||this.form.get('legalName')?.invalid){this.form.markAllAsTouched();return;}
    this.error = undefined;
    this.sending = true;

    try {
      const user = await this.users.signInWithGoogleAndLoadProfile();
      const uid = user.userId;
      const now = Date.now();

      const v = this.form.value;
      const displayName = (v.displayName || user.displayName || '').trim();
      const firstname = v.firstname || (displayName.split(' ')[0] || '');
      const lastname = v.lastname || (displayName.split(' ').slice(1).join(' ') || '');
      const role = ['assetOwner','boatOwner','owner','concierge','admin'].includes(String(user.role)) ? user.role : registrationRole(v.role);

      const profile = {
        userId: uid,
        firstname,
        lastname,
        country: v.country || '',
        stripeAccountId: '',
        stripeAccountStatus: '',
        email: user.email || v.email || '',
        phone: v.phone || user.phone || '',
        role,
        photos: this.photoUrls.length ? this.photoUrls : (user.photoURL ? [user.photoURL] : []),
        socialnetwork: (v.socialnetwork || []).map((s: any) => ({
          label: s.label || '',
          url: s.url || '',
        })) as SocialLink[],
        emailverified: !!user.emailverified,
        state: 'active',
        displayName,
        createdTS: now,
        modifiedTS: now,
        photoURL: (this.photoUrls[0] || user.photoURL || ''),
        provider: 'google',
      };

      const catalog=await this.legal.catalog(registrationRole(role));
      if(catalog.bundleHash!==this.legalCatalog.bundleHash){await this.router.navigate(['/account/accept-terms'],{queryParams:{role:catalog.role,returnUrl:'/account/profile'}});return;}
      await this.legal.accept(catalog,v.legalName,v.adultConfirmed);
      await this.registrationProfile.save(profile);

      // IMMEDIATE redirect to home (no “user created” banner)
      // If you want to auto-open Stripe right after Google for owners/providers, uncomment below:
      // if (this.isOwnerOrProvider(role) && this.connectStripeNow) {
      //   window.location.href = this.buildStripeAuthorizeUrl(uid, role);
      //   return;
      // }
      if(this.publishIntent)try{sessionStorage.removeItem('redirectAfterLogin');}catch{}
      this.router.navigateByUrl(this.publishIntent?'/owner/listings':'/');
    } catch (e: any) {
      this.openErrorModal(e?.message || 'Google sign-in failed.');
    } finally {
      this.sending = false;
    }
  }
}
